(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*18 + Math.cos(y*0.013-t*0.2)*12;
  const w1y = Math.cos(y*0.018-t*0.25)*18 + Math.sin(x*0.015+t*0.35)*12;
  const sx = x + w1x, sy = y + w1y;
  const w2x = Math.sin(sx*0.025-t*0.5)*8 + Math.cos(sy*0.02+t*0.4)*6;
  const w2y = Math.cos(sy*0.025+t*0.45)*8 + Math.sin(sx*0.022-t*0.55)*6;
  const dx = sx + w2x, dy = sy + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.6+4)*50, 0.11, 2.1],
    [400+Math.cos(t*0.45+2)*60, 220+Math.sin(t*0.8+1)*40, 0.085, 1.8]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((dx-sX)**2 + (dy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
  }
  const act = aS/8, inh = iS/8;
  const bg = (Math.sin(dx*0.04+dy*0.025+t*0.8) + Math.sin(dx*0.03-dy*0.04+t*1.1))/2
    + Math.sin((dx+dy)*0.12+t*2.5)*0.2 + Math.sin((dx-dy)*0.1-t*2)*0.2;
  const dist = Math.sqrt((dx-cx)**2 + (dy-cy)**2), ang = Math.atan2(dy-cy, dx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2)
    + Math.sin(dist*0.08-ang*2+t*0.9)*0.5 + Math.sin(dist*0.03+ang*6-t*2.2)*0.4)*0.3;
  const micro = Math.sin(dx*0.35+t*3)*Math.sin(dy*0.35-t*2.5)*Math.sin((dx-dy)*0.25+t*1.8)*0.15;
  const reaction = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + micro)*2.2);
  const cell = Math.tanh((Math.sin(dx*0.15)*Math.sin(dy*0.15) + Math.sin((dx+dy)*0.1+t)*0.5)*1.5)*0.3;
  const ridge = (1 - Math.abs(Math.sin(dx*0.08+dy*0.06+t*0.7)))*0.12;
  const blend = reaction*0.65 + cell*0.2 + ridge*0.15, v = blend*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,85],[12,85,105],[18,130,125],
    [55,165,120],[160,185,70],[210,175,50],[215,130,60],
    [185,80,55],[130,40,60],[70,18,48],[5,12,52]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge = Math.abs(reaction)>0.65?1.12:1.0;
  const vig = 1.0 - Math.sqrt((x-cx)**2+(y-cy)**2)/400*0.15;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig)|0
  ];
}
